<div class="breadcrumbs"><a href="<?= $link('/organizations/'.$organization['id']) ?>"><?= $e($organization['name']) ?></a><span>/</span><a href="<?= $link('/organizations/'.$organization['id'].'/'.$record['type']) ?>"><?= $e(ucfirst($record['type']).'s') ?></a></div>
<div class="section-actions"><div class="record-meta"><span class="badge <?= $record['visibility']==='client'?'shared':'' ?>"><?= $record['visibility']==='internal'?'Internal only':'Client visible' ?></span><?php if($record['category']): ?><span class="badge"><?= $e($record['category']) ?></span><?php endif; ?><?php foreach($record['tags'] as $tag): ?><span class="tag"><?= $e($tag) ?></span><?php endforeach; ?></div><?php if($canWrite): ?><a class="button" href="<?= $link('/records/'.$record['id'].'/edit') ?>">Edit <?= $e($record['type']) ?></a><?php endif; ?></div>
<div class="record-layout"><section class="card record-content">
<?php $payload=$record['payload'];if($record['type']==='article'): ?><div class="article-content"><?= $payload['html'] ?></div>
<?php elseif($record['type']==='asset'): ?><h2><?= $e($definition['name']) ?></h2><dl class="detail-list"><?php foreach($definition['fields'] as $f): $v=$payload['values'][$f['id']]??null;if($f['archived']&&$actor->audience==='client')continue; ?><dt><?= $e($f['name']) ?><?= $f['archived']?' (archived field)':'' ?></dt><dd><?= $e(is_bool($v)?($v?'Yes':'No'):($v??'—')) ?></dd><?php endforeach; ?><?php foreach($references as [$key,$r]): ?><dt><?= $key==='location_id'?'Location':'Primary contact' ?></dt><dd><a href="<?= $link('/records/'.$r['id']) ?>"><?= $e($r['title']) ?></a></dd><?php endforeach; ?></dl><?php if(!empty($payload['notes'])): ?><h3>Notes</h3><p class="preserve-lines"><?= $e($payload['notes']) ?></p><?php endif; ?>
<?php else: ?><dl class="detail-list"><?php foreach($payload as $key=>$value): ?><dt><?= $e(ucfirst(str_replace('_',' ',$key))) ?></dt><dd class="preserve-lines"><?= $e($value?:'—') ?></dd><?php endforeach; ?></dl><?php endif; ?>
<p class="help">Updated <?= $e($record['updated_at']) ?> UTC · Revision <?= $e($record['revision']) ?></p></section>
<aside class="record-aside"><section class="card"><h2>Related records</h2><?php if(!$relationships): ?><p class="muted">No related records.</p><?php else: ?><ul class="record-links"><?php foreach($relationships as $r): ?><li><div><small class="muted"><?= $e(ucfirst($r['type'])) ?></small><a href="<?= $link('/records/'.$r['id']) ?>"><?= $e($r['title']) ?></a></div><?php if($canWrite): ?><form method="post" action="<?= $link('/records/'.$record['id'].'/relationships/'.$r['relationship_id'].'/delete') ?>"><?= $csrf ?><button class="text-link" aria-label="Unlink <?= $e($r['title']) ?>">Unlink</button></form><?php endif; ?></li><?php endforeach; ?></ul><?php endif; ?>
<?php if($canWrite&&$targets): ?><form method="post" action="<?= $link('/records/'.$record['id'].'/relationships') ?>"><?= $csrf ?><label>Link another record<select name="target_id" required><option value="">Select record…</option><?php foreach($targets as $t): ?><option value="<?= $e($t['id']) ?>"><?= $e(ucfirst($t['type']).' · '.$t['title']) ?></option><?php endforeach; ?></select></label><button class="button secondary small">Add relationship</button></form><?php endif; ?></section>
<section class="card"><h2>Attachments</h2><?php if(!$attachments): ?><p class="muted">No attachments.</p><?php else: ?><ul class="record-links"><?php foreach($attachments as $f): ?><li><div><a href="<?= $link('/attachments/'.$f['id']) ?>"><?= $e($f['name']) ?></a><small class="muted"><?= $e(number_format($f['bytes']/1024,1)) ?> KB</small></div><?php if($canWrite): ?><form method="post" action="<?= $link('/attachments/'.$f['id'].'/delete') ?>" data-confirm="Permanently delete this attachment?"><?= $csrf ?><button class="text-link danger-text">Delete</button></form><?php endif; ?></li><?php endforeach; ?></ul><?php endif; ?>
<?php if($canWrite): ?><form method="post" enctype="multipart/form-data" action="<?= $link('/records/'.$record['id'].'/attachments') ?>"><?= $csrf ?><label>Add attachment<input name="attachment" type="file" required></label><p class="help">Documents and images. Maximum <?= $e(round(($ctx->config['upload_limit']??20971520)/1048576)) ?> MiB; your PHP upload limit also applies.</p><button class="button secondary small">Upload file</button></form><?php endif; ?></section></aside></div>
<?php if($history): ?><section class="card"><h2>Article history</h2><div class="table-scroll"><table><thead><tr><th>Revision</th><th>Author</th><th>Saved (UTC)</th><th></th></tr></thead><tbody><?php foreach($history as $h): ?><tr><td><?= $e($h['number']) ?></td><td><?= $e($h['author']) ?></td><td><?= $e($h['created_at']) ?></td><td><a href="<?= $link('/records/'.$record['id'].'/revisions/'.$h['id']) ?>">View and compare</a></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<?php if($canWrite): ?><details class="card danger-zone"><summary>Archive this record</summary><p>Archived records are hidden from normal lists and search. Staff can restore them later.</p><form method="post" action="<?= $link('/records/'.$record['id'].'/archive') ?>" data-confirm="Archive this record?"><?= $csrf ?><button class="button danger">Archive record</button></form></details><?php endif; ?>
